<template><div><section class="bg-primary-950 py-14 text-white"><div class="container-page max-w-3xl"><p class="text-sm font-semibold uppercase tracking-wider text-primary-200">Property knowledge</p><h1 class="mt-3 text-4xl sm:text-5xl">Real Estate Guides &amp; Insights</h1><p class="mt-4 text-lg text-primary-100">Practical guidance for buying land, comparing payment plans and making informed property decisions in Nigeria.</p></div></section><section class="section"><div class="container-page"><div v-if="posts?.length" class="grid gap-7 md:grid-cols-2 lg:grid-cols-3"><article v-for="post in posts" :key="post.id" class="card overflow-hidden"><NuxtLink :to="`/blog/${post.slug}`"><NuxtImg v-if="post.featured_image" :src="post.featured_image" :alt="post.title" class="h-48 w-full object-cover"/><div v-else class="flex h-48 items-center justify-center bg-primary-100 text-primary-700"><Newspaper class="h-12 w-12"/></div></NuxtLink><div class="p-6"><p class="text-xs font-semibold uppercase tracking-wider text-primary-700">{{post.category_name||'Property Guide'}}</p><h2 class="mt-2 text-xl"><NuxtLink :to="`/blog/${post.slug}`" class="hover:text-primary-700">{{post.title}}</NuxtLink></h2><p class="mt-3 line-clamp-3 text-sm leading-6 text-neutral-600">{{post.excerpt}}</p><NuxtLink :to="`/blog/${post.slug}`" class="mt-5 inline-flex font-semibold text-primary-700">Read article →</NuxtLink></div></article></div><p v-else-if="!pending" class="rounded-xl bg-neutral-100 p-6">Property guides will appear here when published.</p></div></section></div></template>
<script setup lang="ts">import{Newspaper}from'lucide-vue-next';const config=useRuntimeConfig();const{data:posts,pending}=useAsyncData('public-blog',async()=>{const{data,error}=await useSupabase().from('blog_posts').select('*').eq('published',true).order('published_at',{ascending:false});if(error)throw error;return data||[]});const canonical=`${config.public.siteUrl.replace(/\/$/,'')}/blog`;useSeoMeta({title:'Nigeria Real Estate Guides | Lexshield Properties',description:'Read practical guides about buying land, property payment plans, inspections and real estate investment in Nigeria.',ogTitle:'Lexshield Property Guides',ogType:'website',ogUrl:canonical});useHead({link:[{rel:'canonical',href:canonical}]})</script>
